import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"Multiplayer","description":"","frontmatter":{},"headers":[],"relativePath":"Other/Multiplayer.md","filePath":"Other/Multiplayer.md"}'),l={name:"Other/Multiplayer.md"};function i(n,e,s,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="multiplayer" tabindex="-1">Multiplayer <a class="header-anchor" href="#multiplayer" aria-label="Permalink to &quot;Multiplayer&quot;">​</a></h1><p>UncivCN online multiplayer connects to the closed-source Go server (UncivSrv) run by the community at <code>https://unciv.civgo.top:30123</code>. The address is fixed in the client. Games hosted on other servers do not transfer automatically.</p><h2 id="how-to-play" tabindex="-1">How to play <a class="header-anchor" href="#how-to-play" aria-label="Permalink to &quot;How to play&quot;">​</a></h2><ol start="0"><li>In <code>Main Menu -&gt; Options -&gt; Multiplayer</code>, select <code>Check connection</code>.</li><li>Let all players send you their user ID (<code>Main Menu -&gt; Multiplayer -&gt; Copy user ID</code>). <ul><li>(Optional) Add those user IDs to your friend list (<code>Main Menu -&gt; Multiplayer -&gt; Friends list</code>).</li></ul></li><li>In <code>Main Menu -&gt; Start new game</code>, check <code>Online multiplayer</code> on the left. On the right, add more human players and input the user IDs of the players you want to play with. Press <code>Start game!</code>.</li><li>The game ID will be automatically put in your clipboard. (If you lost it, you can get it again from <code>Main Menu -&gt; Multiplayer -&gt; Copy game ID</code>). Send this game ID to the other players.</li><li>The other players need to go to <code>Main Menu -&gt; Multiplayer -&gt; Add multiplayer game</code> and enter the game ID you just sent them. They can then join the game from this multiplayer screen.</li></ol><p>When the host enables restart voting, a surviving player can start a vote from the in-game menu on the configured turn. The vote ends when all surviving players have voted or the deadline passes. Players who miss the deadline count as agreeing; a tie also passes. UncivSrv keeps the vote across reconnects and server restarts. A passed vote creates a new game with the same setup.</p>',5)])])}const y=t(l,[["render",i]]);export{p as __pageData,y as default};
